    {
      "name": "Finsupp.prod_eq_zero_iff",
      "module_name": "Mathlib.Algebra.BigOperators.Finsupp.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {ι : Type u_2} {β : Type u_7} [inst : Zero α] [inst_1 : CommMonoidWithZero β] [Nontrivial β]\n  [NoZeroDivisors β] {f : ι →₀ α} {g : ι → α → β}, f.prod g = 0 ↔ ∃ i ∈ f.support, g i (f i) = 0"
    },
    {
      "name": "DFinsupp.prod_eq_zero_iff",
      "module_name": "Mathlib.Data.DFinsupp.BigOperators",
      "kind": "theorem",
      "type": "∀ {ι : Type u} {γ : Type w} {β : ι → Type v} [inst : DecidableEq ι] [inst_1 : (i : ι) → Zero (β i)]\n  [inst_2 : CommMonoidWithZero γ] [Nontrivial γ] [NoZeroDivisors γ] [inst_5 : (i : ι) → DecidableEq (β i)]\n  {f : Π₀ (i : ι), β i} {g : (i : ι) → β i → γ}, f.prod g = 0 ↔ ∃ i ∈ f.support, g i (f i) = 0"
    },
    {
      "name": "finprod_eq_zero",
      "module_name": "Mathlib.Algebra.BigOperators.Finprod",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {M₀ : Type u_7} [inst : CommMonoidWithZero M₀] (f : α → M₀) (x : α),\n  f x = 0 → (Function.mulSupport f).Finite → ∏ᶠ (x : α), f x = 0"
    },
    {
      "name": "Cardinal.prod_eq_zero",
      "module_name": "Mathlib.SetTheory.Cardinal.Defs",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} (f : ι → Cardinal.{u}), Cardinal.prod f = 0 ↔ ∃ i, f i = 0"
    },
    {
      "name": "Finsupp.prod_ne_zero_iff",
      "module_name": "Mathlib.Algebra.BigOperators.Finsupp.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {ι : Type u_2} {β : Type u_7} [inst : Zero α] [inst_1 : CommMonoidWithZero β] [Nontrivial β]\n  [NoZeroDivisors β] {f : ι →₀ α} {g : ι → α → β}, f.prod g ≠ 0 ↔ ∀ i ∈ f.support, g i (f i) ≠ 0"
    }
  ]
}

